INSERT INTO sistema_salud.disponibilidad_profesional (id_profesional, id_centro_salud, dia_semana, hora_inicio, hora_fin, duracion_turno_minutos, modalidad_permitida, activa) SELECT p.id_profesional, p.id_centro_salud, d.dia_semana, '08:00:00', '17:00:00', 15, 'PRESENCIAL', TRUE FROM sistema_salud.profesional p CROSS JOIN (SELECT 'LUNES' dia_semana UNION SELECT 'MARTES' UNION SELECT 'MIERCOLES' UNION SELECT 'JUEVES' UNION SELECT 'VIERNES' UNION SELECT 'SABADO' UNION SELECT 'DOMINGO') d WHERE p.id_profesional = (SELECT id_profesional FROM sistema_salud.profesional WHERE id_usuario = (SELECT id_usuario FROM sistema_salud.usuario WHERE email='diego.pereyra.sanroque@salud.com'));
